CREATE DEFINER=`user`@`%` PROCEDURE `check_tout_distribution`(
  IN p1  TINYINT UNSIGNED, IN p2  TINYINT UNSIGNED, IN p3  TINYINT UNSIGNED,
  IN p4  TINYINT UNSIGNED, IN p5  TINYINT UNSIGNED, IN p6  TINYINT UNSIGNED,
  IN p7  TINYINT UNSIGNED, IN p8  TINYINT UNSIGNED, IN p9  TINYINT UNSIGNED,
  IN p10 TINYINT UNSIGNED, IN p11 TINYINT UNSIGNED, IN p12 TINYINT UNSIGNED
)
BEGIN
  /* === Валидация: 12 уникальных чисел 1..24 === */
  DECLARE v_total INT;
  DECLARE v_distinct INT;
  DECLARE v_min TINYINT UNSIGNED;
  DECLARE v_max TINYINT UNSIGNED;

  SELECT COUNT(*) AS total,
         COUNT(DISTINCT v) AS distinct_cnt,
         MIN(v) AS vmin,
         MAX(v) AS vmax
  INTO   v_total, v_distinct, v_min, v_max
  FROM (
    SELECT p1 AS v UNION ALL SELECT p2 UNION ALL SELECT p3 UNION ALL SELECT p4
    UNION ALL SELECT p5 UNION ALL SELECT p6 UNION ALL SELECT p7 UNION ALL SELECT p8
    UNION ALL SELECT p9 UNION ALL SELECT p10 UNION ALL SELECT p11 UNION ALL SELECT p12
  ) t;

  IF v_total <> 12 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Invalid input: need exactly 12 numbers';
  END IF;
  IF v_distinct <> 12 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Invalid input: numbers must be 12 distinct values';
  END IF;
  IF v_min < 1 OR v_max > 24 THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Invalid input: numbers must be in range 1..24';
  END IF;

  /* === Подсчёт === */
  SELECT
    b.k AS matches,
    CASE b.k
      WHEN 0  THEN '0 sovpadeniy'
      WHEN 1  THEN '1 sovpad'
      WHEN 2  THEN '2 sovpad'
      WHEN 3  THEN '3 sovpad'
      WHEN 4  THEN '4 sovpad'
      WHEN 8  THEN '8 sovpad'
      WHEN 9  THEN '9 sovpad'
      WHEN 10 THEN '10 sovpad'
      WHEN 11 THEN '11 sovpad'
      WHEN 12 THEN '12 sovpad'
    END AS bucket_label,
    COALESCE(a.draws_count, 0) AS cnt,
    COALESCE(a.draws_count, 0) *
    CASE b.k
      WHEN 0  THEN 250000
      WHEN 1  THEN 1000
      WHEN 2  THEN 25
      WHEN 3  THEN 10
      WHEN 4  THEN 2
      WHEN 8  THEN 2
      WHEN 9  THEN 10
      WHEN 10 THEN 25
      WHEN 11 THEN 1000
      WHEN 12 THEN 250000
      ELSE 0
    END AS prize_sum
  FROM
    ( SELECT 0 AS k UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3
      UNION ALL SELECT 4 UNION ALL SELECT 8 UNION ALL SELECT 9
      UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12
    ) b
  LEFT JOIN (
    SELECT matches, COUNT(*) AS draws_count
    FROM (
      SELECT (
        (n1  IN (p1,p2,p3,p4,p5,p6,p7,p8,p9,p10,p11,p12)) +
        (n2  IN (p1,p2,p3,p4,p5,p6,p7,p8,p9,p10,p11,p12)) +
        (n3  IN (p1,p2,p3,p4,p5,p6,p7,p8,p9,p10,p11,p12)) +
        (n4  IN (p1,p2,p3,p4,p5,p6,p7,p8,p9,p10,p11,p12)) +
        (n5  IN (p1,p2,p3,p4,p5,p6,p7,p8,p9,p10,p11,p12)) +
        (n6  IN (p1,p2,p3,p4,p5,p6,p7,p8,p9,p10,p11,p12)) +
        (n7  IN (p1,p2,p3,p4,p5,p6,p7,p8,p9,p10,p11,p12)) +
        (n8  IN (p1,p2,p3,p4,p5,p6,p7,p8,p9,p10,p11,p12)) +
        (n9  IN (p1,p2,p3,p4,p5,p6,p7,p8,p9,p10,p11,p12)) +
        (n10 IN (p1,p2,p3,p4,p5,p6,p7,p8,p9,p10,p11,p12)) +
        (n11 IN (p1,p2,p3,p4,p5,p6,p7,p8,p9,p10,p11,p12)) +
        (n12 IN (p1,p2,p3,p4,p5,p6,p7,p8,p9,p10,p11,p12))
      ) AS matches
      FROM Tout
    ) mm
    GROUP BY matches
  ) a
  ON a.matches = b.k
  ORDER BY b.k;
END ;;
